function countPeaksAndDips(heights: number[]): number {
  const n = heights.length;
  let count = 0;
  for (let i = 0; i < n; i++) {
    if (i > 0 && heights[i - 1] === heights[i]) continue; // already handled this run
    let l = i - 1, r = i + 1;
    while (l >= 0 && heights[l] === heights[i]) l--;
    while (r < n && heights[r] === heights[i]) r++;
    if (l < 0 || r >= n) continue;
    const up = heights[l] < heights[i] && heights[r] < heights[i];
    const down = heights[l] > heights[i] && heights[r] > heights[i];
    if (up || down) count++;
  }
  return count;
}

