class Solution:
    def countPeaksAndDips(self, heights: List[int]) -> int:
        n = len(heights)
        count = 0
        for i in range(n):
            if i > 0 and heights[i - 1] == heights[i]:
                continue
            l, r = i - 1, i + 1
            while l >= 0 and heights[l] == heights[i]:
                l -= 1
            while r < n and heights[r] == heights[i]:
                r += 1
            if l < 0 or r >= n:
                continue
            a, b, c = heights[l], heights[i], heights[r]
            if (a < b > c) or (a > b < c):
                count += 1
        return count

