function countPeaksAndDips(heights: number[]): number {
  const flat: number[] = [];
  for (const h of heights) if (flat.length === 0 || flat[flat.length - 1] !== h) flat.push(h);
  let count = 0;
  for (let i = 1; i + 1 < flat.length; i++) {
    const a = flat[i - 1], b = flat[i], c = flat[i + 1];
    if ((b > a && b > c) || (b < a && b < c)) count++;
  }
  return count;
}

