function countPeaksAndDips(heights: number[]): number {
  let count = 0;
  let prev = heights[0]; // last height that differs from the current run
  for (let i = 1; i + 1 < heights.length; i++) {
    const h = heights[i], next = heights[i + 1];
    if (h === next) continue; // judge the run at its last element
    if (h !== prev && ((h > prev && h > next) || (h < prev && h < next))) count++;
    prev = h;
  }
  return count;
}

