    def countPeaksAndDips(self, heights: List[int]) -> int:
        count = 0
        prev = heights[0]
        for i in range(1, len(heights) - 1):
            h, nxt = heights[i], heights[i + 1]
            if h == nxt:
                continue
            if h != prev and ((h > prev and h > nxt) or (h < prev and h < nxt)):
                count += 1
            prev = h
        return count

